/**
 * What the generated files of a client declare or export for themselves: the imports of
 * `operations.ts`, the exports of `client.ts`, `errors.ts` and `runtime.ts` that `index.ts`
 * re-exports. An operation or a schema named so would clash with one, or be hidden by it.
 */
export const CLIENT_NAMES: ReadonlySet<string> = new Set([
  'Schemas',
  'send',
  'Operation',
  'Connection',
  'Client',
  'SchemeName',
  'connect',
  'createClient',
  'ERROR_CODES',
  'ErrorCode',
  'ProblemOf',
  'isErrorCode',
  'isProblem',
  'CallOptions',
  'ClientOptions',
  'Credential',
  'DataOf',
  'Failure',
  'ProblemError',
  'Success',
  'UnexpectedResponseError',
  'unwrap',
]);
